"""Writes the key poses (poses.py) as the mod's table, src/rac1/ride_poses.inc: per pose, each
turned joint's local offset (q * d) over his standing pose.

    python3 tools/poses/export.py <levels>/level_01/mobys/moby_0.glb src/rac1/ride_poses.inc
"""
import sys
from poses import *
r = Rig(sys.argv[1])
out = ["// SPDX-License-Identifier: MIT", "// Copyright (c) 2026 Mateusz Kłysz",
       "// Ratchet's riding key poses, our own, as joint offsets over his standing pose (seq 0).",
       "// Generated by tools/poses/export.py from tools/poses/poses.py; do not edit by hand.", "#pragma once", "",
       '#include "rac1/ride_pose.hpp"', "", "namespace rac1::poses {", ""]
names = list(POSES)
for n in names:
    w, t = POSES[n]
    d = r.deltas_from_world(0, 0, w)
    out.append(f"constexpr JointTurn k_{n}[] = {{")
    for k in sorted(d):
        q = d[k]
        if q[3] < 0: q = -q
        out.append(f"    {{{k}, {{{q[0]:.5f}f, {q[1]:.5f}f, {q[2]:.5f}f, {q[3]:.5f}f}}}},")
    out.append("};")
    tz = t[1][2]
    out.append(f"constexpr KeyPose {n}{{k_{n}, sizeof(k_{n}) / sizeof(k_{n}[0]), {{{t[1][0]:.3f}f, {t[1][1]:.3f}f, {tz:.3f}f}}}};")
    out.append("")
# The secondary-motion channels: each turn's axis in the joint's own frame (standing pose).
rot, tr = r.local_pose(0, 0)
G = r.globals(rot, tr)
for n, turns in CHANNELS.items():
    out.append(f"constexpr ChannelTurn c_{n}[] = {{")
    for j, axis, deg in turns:
        a = np.asarray(axis, float); a = a / np.linalg.norm(a)
        loc = G[j][:3, :3].T @ a
        out.append(f"    {{{j}, {{{loc[0]:.5f}f, {loc[1]:.5f}f, {loc[2]:.5f}f}}, {deg:.1f}f}},")
    out.append("};")
out.append("")
out.append("// Channels, in the order of rac1::Channel.")
out.append("constexpr Chan kChannels[] = {")
for n in CHANNELS:
    out.append(f"    {{c_{n}, sizeof(c_{n}) / sizeof(c_{n}[0])}},  // {n}")
out.append("};")
out.append("")
out.append("} // namespace rac1::poses")
open(sys.argv[2], 'w').write("\n".join(out) + "\n")
print(names, list(CHANNELS))
